// Title: Remove extra whitespace after <br> tags in HTML output generated by Aspose.Cells for .NET (C#)
// Common Searches: how to trim spaces after <br> in Aspose.Cells HTML export using C# | C# regex to remove trailing whitespace after line break tags in workbook HTML | Aspose.Cells save workbook as HTML5 without blank characters after <br/> | clean up Aspose.Cells generated HTML to eliminate spaces after <br> tags | remove whitespace following <br> tags in HTML produced by Aspose.Cells .NET
// Tags: Aspose.Cells HTML whitespace cleanup | C# regex for br tag trimming | HtmlSaveOptions Html5 self-closing br | text wrapping line breaks to <br> Aspose.Cells | export workbook to HTML without trailing spaces

using Aspose.Cells;
using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;

// The example creates a workbook, inserts multiline text into a cell, enables text wrapping so line breaks become <br> tags, saves the sheet as HTML5, reads the generated HTML, and uses a regular expression to replace any <br> (or <br/>) followed by whitespace with a self‑closing <br/> tag, producing clean HTML without extra spaces.
class Program
{
    static void Main()
    {
        // Create a new workbook
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];

        // Put a value containing line breaks into a cell
        sheet.Cells["A1"].PutValue("First line\nSecond line\nThird line");

        // Enable text wrapping so line breaks are rendered as <br> in HTML
        Style style = sheet.Cells["A1"].GetStyle();
        style.IsTextWrapped = true;
        sheet.Cells["A1"].SetStyle(style);

        // Set HTML save options to use HTML5 (produces <br/> tags)
        HtmlSaveOptions htmlOptions = new HtmlSaveOptions(SaveFormat.Html);
        htmlOptions.HtmlVersion = HtmlVersion.Html5;

        // Save the workbook to a memory stream
        using (MemoryStream ms = new MemoryStream())
        {
            workbook.Save(ms, htmlOptions);
            ms.Position = 0;

            // Read the generated HTML
            string html = new StreamReader(ms, Encoding.UTF8).ReadToEnd();

            // Remove any spaces that appear after <br> tags
            // Replace <br> with self‑closing <br/> and trim trailing whitespace
            html = Regex.Replace(html, @"<br\s*/?>\s+", "<br/>");

            // Write the cleaned HTML to a file
            File.WriteAllText("output.html", html, Encoding.UTF8);
        }
    }
}
